package com.example.battleshipgame.views;
import android.os.Bundle;import android.view.Gravity;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import com.example.battleshipgame.ui.Ui;
public class HistoryActivity extends AppCompatActivity{@Override public void onCreate(Bundle state){super.onCreate(state);LinearLayout page=Ui.page(this);page.setGravity(Gravity.CENTER_HORIZONTAL);TextView e=Ui.text(this,"BATTLE LOG",11,Ui.CYAN);e.setLetterSpacing(.16f);Ui.spaced(page,e,24);TextView h=Ui.text(this,"היסטוריית קרבות",28,Ui.INK);h.setTypeface(null,1);Ui.spaced(page,h,4);String latest=getSharedPreferences("history",0).getString("last",null);TextView record=Ui.card(this,latest==null?"אין קרבות מתועדים":"הקרב האחרון",latest==null?"צא למשימה חדשה כדי למלא את יומן הקרבות שלך.":latest);Ui.spaced(page,record,30);TextView detail=Ui.text(this,"היסטוריית משחקים מלאה תתווסף לאחר חיבור מסד הנתונים.",14,Ui.MUTED);Ui.spaced(page,detail,14);Button back=Ui.button(this,"חזרה לתפריט",true);back.setOnClickListener(v->finish());Ui.spaced(page,back,32);setContentView(page);}}
